@datatype class ProcessorTimingProperties(val clockPeriod: Option[Z],
                                          val framePeriod: Option[Z],
                                          val maxDomain: Option[Z],
                                          val slotTime: Option[Z])

@datatype class ThreadTimingProperties(val domain: Option[Z],
                                       val computeExecutionTime: Option[(Z, Z)])

object Schedulers {

  val threadNickNames: Map[String, Art.BridgeId] = Map(
    ISZ(
      Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_doctor_request_qualification.name ~> Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_doctor_request_qualification.id,
      Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_preparation_assessment.name ~> Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_preparation_assessment.id,
      Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_equipment_assessment.name ~> Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_equipment_assessment.id,
      Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_batch_assessment.name ~> Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_batch_assessment.id,
      Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_result_assessment.name ~> Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_result_assessment.id,
      Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_fault_composition.name ~> Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_fault_composition.id,
      Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_session_control.name ~> Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_session_control.id,
      Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_acquisition_cycle_control.name ~> Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_acquisition_cycle_control.id,
      Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_availability_control.name ~> Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_availability_control.id,
      Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_recovery_control.name ~> Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_recovery_control.id,
      Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_start_feasibility.name ~> Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_start_feasibility.id,
      Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_collection_feasibility.name ~> Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_collection_feasibility.id,
      Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_release_feasibility.name ~> Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_release_feasibility.id,
      Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_supervisory_arbitration.name ~> Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_supervisory_arbitration.id,
      Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_publication_composition.name ~> Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_publication_composition.id)
  )

  val revThreadNickNames: Map[Art.BridgeId, String] = Map.empty[Art.BridgeId, String] ++ (for (e <- threadNickNames.entries) yield e._2 ~> e._1)


  val EITAcquisitionSupervisorSystem_Instance_acquisition_process_doctor_request_qualification_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val EITAcquisitionSupervisorSystem_Instance_acquisition_process_preparation_assessment_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val EITAcquisitionSupervisorSystem_Instance_acquisition_process_equipment_assessment_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val EITAcquisitionSupervisorSystem_Instance_acquisition_process_batch_assessment_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_result_assessment_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val EITAcquisitionSupervisorSystem_Instance_acquisition_process_fault_composition_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
