  val EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_availability_control_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val EITAcquisitionSupervisorSystem_Instance_acquisition_process_recovery_control_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val EITAcquisitionSupervisorSystem_Instance_acquisition_process_start_feasibility_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val EITAcquisitionSupervisorSystem_Instance_acquisition_process_collection_feasibility_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_release_feasibility_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val EITAcquisitionSupervisorSystem_Instance_acquisition_process_supervisory_arbitration_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())

  val EITAcquisitionSupervisorSystem_Instance_acquisition_process_publication_composition_timingProperties: ThreadTimingProperties = ThreadTimingProperties(
    computeExecutionTime = None(),
    domain = None())


  /**********************************************************************
   * Round Robin Scheduler
   *********************************************************************/

  // roundRobinSchedule represents the component dispatch order
  val roundRobinSchedule: ISZ[Art.BridgeId] = {
    // convert IS[Art.BridgeId, art.Bridge] to an IS[Z, Art.BridgeId] to allow bridges to be dispatched
    // multiple times during a hyper-period
    var ret: ISZ[Art.BridgeId] = ISZ()
    for (e <- Arch.ad.components) {
      ret = ret :+ e.id
    }
    ret
  }

  def getRoundRobinScheduler(schedule: Option[ISZ[Art.BridgeId]]): RoundRobin = {
    if (roundRobinSchedule.isEmpty) {} // line needed for transpiler; do not remove
    schedule match {
      case Some(s) => return RoundRobin(s)
      case _ => return RoundRobin(ScheduleProviderI.getRoundRobinOrder())
    }
  }

  /**********************************************************************
   * Static Scheduler
   *********************************************************************/

  val framePeriod: Z = 1000
  val numComponents: Z = Arch.ad.components.size
  val maxExecutionTime: Z = numComponents / framePeriod

  // defaultStaticSchedule represents the component dispatch order
  val defaultStaticSchedule: DScheduleSpec = DScheduleSpec(0, 0, DSchedule(ISZ(
    Schedule.Slot(0, maxExecutionTime),
    Schedule.Slot(1, maxExecutionTime),
    Schedule.Slot(2, maxExecutionTime),
    Schedule.Slot(3, maxExecutionTime),
    Schedule.Slot(4, maxExecutionTime),
    Schedule.Slot(5, maxExecutionTime),
    Schedule.Slot(6, maxExecutionTime),
    Schedule.Slot(7, maxExecutionTime),
    Schedule.Slot(8, maxExecutionTime),
    Schedule.Slot(9, maxExecutionTime),
    Schedule.Slot(10, maxExecutionTime),
    Schedule.Slot(11, maxExecutionTime),
    Schedule.Slot(12, maxExecutionTime),
    Schedule.Slot(13, maxExecutionTime),
    Schedule.Slot(14, maxExecutionTime)
  )))

  val defaultDomainToBridgeIdMap: ISZ[Art.BridgeId] = ISZ(
    /* domain 0 */ Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_doctor_request_qualification.id,
    /* domain 1 */ Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_preparation_assessment.id,
    /* domain 2 */ Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_equipment_assessment.id,
    /* domain 3 */ Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_batch_assessment.id,
    /* domain 4 */ Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_result_assessment.id,
    /* domain 5 */ Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_fault_composition.id,
    /* domain 6 */ Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_session_control.id,
    /* domain 7 */ Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_acquisition_cycle_control.id,
    /* domain 8 */ Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_availability_control.id,
    /* domain 9 */ Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_recovery_control.id,
    /* domain 10 */ Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_start_feasibility.id,
    /* domain 11 */ Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_collection_feasibility.id,
    /* domain 12 */ Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_image_release_feasibility.id,
    /* domain 13 */ Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_supervisory_arbitration.id,
    /* domain 14 */ Arch.EITAcquisitionSupervisorSystem_Instance_acquisition_process_publication_composition.id
  )

  def getStaticSchedulerH(userProvided: MOption[(DScheduleSpec, ISZ[Art.BridgeId], Map[String, Art.BridgeId], CommandProvider)]): StaticScheduler = {
    if (defaultStaticSchedule.schedule.slots.isEmpty && defaultDomainToBridgeIdMap.isEmpty && threadNickNames.isEmpty) {} // line needed for transpiler; do not remove
    userProvided match {
      case MSome((schedule_, domainToBridgeIdMap_, threadNickNames_, commandProvider)) =>
        return getStaticScheduler(schedule_, domainToBridgeIdMap_, threadNickNames_, commandProvider)
      case _ =>
        return getStaticScheduler(
          ScheduleProviderI.getStaticSchedule(),
          // TODO: get the following from extension so they can be customized via C
          defaultDomainToBridgeIdMap,
          threadNickNames,
          DefaultCommandProvider())
    }
  }

  def getStaticScheduler(schedule: DScheduleSpec,
                         domainToBridgeIdMap: ISZ[Art.BridgeId],
                         threadNickNames: Map[String, Art.BridgeId],
                         commandProvider: CommandProvider): StaticScheduler = {
    return StaticScheduler(schedule, Arch.ad.components, domainToBridgeIdMap, threadNickNames,
      if (commandProvider.isInstanceOf[InfoCommandProvider])
        commandProvider.asInstanceOf[InfoCommandProvider].init(
          threadNickNames,
          schedule.schedule.slots.size,
          domainToBridgeIdMap
        )
      else commandProvider)
  }


  /**********************************************************************
   * Legacy Scheduler
   *********************************************************************/

  def getLegacyScheduler(): Legacy = {
    return Legacy(Arch.ad.components)
  }
}

// the purpose of this extension is to allow users to provide custom schedules
// at the C level after transpiling
@ext(name = "ScheduleProvider") object ScheduleProviderI {
  def getRoundRobinOrder(): ISZ[Art.BridgeId] = $

  def getStaticSchedule(): DScheduleSpec = $
}